80	    /**
81	     * Dedicated audit logger. On successful owner create an audit line is emitted here carrying
82	     * the newly assigned owner id, customer code, registration date, membership level and
83	     * membership number.
84	     */
85	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
