98	    /**
99	     * Remembers, per {@code Idempotency-Key}, the id of the owner originally created for that key,
100	     * so a repeated create with an already-seen key returns the original owner instead of creating
101	     * a duplicate.
102	     */
103	    private final Map<String, Integer> idempotentCreates = new ConcurrentHashMap<>();
