142	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
143	    @Override
144	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
145	        String idempotencyKey = this.request.getHeader("Idempotency-Key");
146	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
147	            Integer existingId = this.idempotentCreates.get(idempotencyKey);
148	            if (existingId != null) {
149	                Owner existing = this.clinicService.findOwnerById(existingId);
150	                if (existing != null) {
151	                    return new ResponseEntity<>(ownerMapper.toOwnerDto(existing), HttpStatus.OK);
152	                }
153	            }
154	        }
155	        normalizeAddress(ownerFieldsDto);
156	        validateRequiredFields(ownerFieldsDto);
157	        validatePostcode(ownerFieldsDto);
158	        normalizeTelephone(ownerFieldsDto);
159	        normalizeEmail(ownerFieldsDto);
160	        rejectDuplicateIdentity(ownerFieldsDto);
161	        rejectDuplicateHousehold(ownerFieldsDto);
162	        rejectCityAtCapacity(ownerFieldsDto.getCity());
163	        rejectFutureRegistrationDate(ownerFieldsDto);
164	        defaultRegistrationDate(ownerFieldsDto);
165	        rejectDailyLimit(ownerFieldsDto.getRegistrationDate());
166	        HttpHeaders headers = new HttpHeaders();
167	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
168	        assignCustomerCode(owner);
169	        assignHouseholdId(owner);
170	        assignHouseholdMemberCount(owner);
171	        assignNamesakeCount(owner);
172	        assignMembershipNumber(owner);
173	        assignBulkSignupWarning(owner);
174	        assignPossibleDuplicate(owner, Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold()));
175	        this.clinicService.saveOwner(owner);
176	        if (idempotencyKey != null && !idempotencyKey.isBlank()) {
177	            this.idempotentCreates.put(idempotencyKey, owner.getId());
178	        }
179	        AUDIT.info("owner created id={} customerCode={} registrationDate={} membershipLevel={} membershipNumber={}",
180	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(), owner.getMembershipLevel(),
181	            owner.getMembershipNumber());
182	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
183	        headers.setLocation(UriComponentsBuilder.newInstance()
184	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
185	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
186	    }
