270	    /**
271	     * Rejects an owner whose mandatory fields ({@code firstName}, {@code lastName},
272	     * {@code address}, {@code city}, {@code telephone}) are missing or blank. Bean
273	     * Validation already rejects {@code null} values and the pattern-constrained fields
274	     * when blank, but {@code address} and {@code city} have no pattern, so a
275	     * whitespace-only value would otherwise slip through.
276	     *
277	     * @param ownerFieldsDto the submitted owner fields
278	     * @throws RequiredFieldsMissingException if any required field is missing or blank
279	     */
280	    /**
281	     * Common street-type abbreviations expanded during address normalization. Keys are the
282	     * upper-cased abbreviation tokens; values are their canonical expansions.
283	     */
284	    private static final Map<String, String> ADDRESS_ABBREVIATIONS = Map.of(
285	        "ST", "STREET",
286	        "RD", "ROAD",
287	        "AVE", "AVENUE");
288	
289	    /**
290	     * Normalizes the submitted address on create, accepting either the structured form
291	     * ({@code addressLine1} plus an optional {@code addressLine2}) or the flat {@code address}
292	     * form retained for backward compatibility. Each supplied field is canonicalized the same way
293	     * (trimmed, internal whitespace collapsed to a single space, upper-cased, and common
294	     * street-type abbreviations expanded — see {@link #ADDRESS_ABBREVIATIONS}), and the normalized
295	     * values are written back onto the request.
296	     *
297	     * <p>The structured fields are preferred when present: when a non-blank {@code addressLine1} is
298	     * supplied, the flat {@code address} is set to the composed value — the normalized
299	     * {@code addressLine1}, with a single space and the normalized {@code addressLine2} appended
300	     * when an {@code addressLine2} is present — otherwise it keeps the normalized flat value. The
301	     * composed {@code address} is therefore persisted, echoed back, and used by everything that
302	     * reads the flat address. A blank/absent value in every form leaves {@code address} blank so the
303	     * required-field check can report it as missing.
304	     *
305	     * @param ownerFieldsDto the submitted owner fields
306	     */
307	    private static void normalizeAddress(OwnerFieldsDto ownerFieldsDto) {
308	        String addressLine1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
309	        String addressLine2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
310	        String flat = normalizeAddress(ownerFieldsDto.getAddress());
311	        ownerFieldsDto.setAddressLine1(addressLine1);
312	        ownerFieldsDto.setAddressLine2(addressLine2);
313	        String composed;
314	        if (addressLine1 != null && !addressLine1.isBlank()) {
315	            composed = (addressLine2 != null && !addressLine2.isBlank())
316	                ? addressLine1 + " " + addressLine2
317	                : addressLine1;
318	        }
319	        else {
320	            composed = flat;
321	        }
322	        ownerFieldsDto.setAddress(composed);
323	    }
324	
325	    /**
326	     * Canonicalizes an address value: trimmed, internal whitespace collapsed to single spaces,
327	     * upper-cased, and each whitespace-delimited token that is a known street-type abbreviation
328	     * expanded to its full form. A {@code null} value is returned unchanged.
329	     *
330	     * @param raw the address to canonicalize, possibly {@code null}
331	     * @return the normalized address, or {@code null} if {@code raw} was {@code null}
332	     */
333	    private static String normalizeAddress(String raw) {
334	        if (raw == null) {
335	            return null;
336	        }
337	        String collapsed = raw.strip().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
338	        if (collapsed.isEmpty()) {
339	            return collapsed;
340	        }
341	        String[] tokens = collapsed.split(" ");
342	        StringBuilder sb = new StringBuilder(collapsed.length());
343	        for (int i = 0; i < tokens.length; i++) {
344	            if (i > 0) {
345	                sb.append(' ');
346	            }
347	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
348	        }
349	        return sb.toString();
350	    }
