352	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
353	        List<String> errors = new ArrayList<>();
354	        requireText("firstName", ownerFieldsDto.getFirstName(), errors);
355	        requireText("lastName", ownerFieldsDto.getLastName(), errors);
356	        requireText("address", ownerFieldsDto.getAddress(), errors);
357	        requireText("city", ownerFieldsDto.getCity(), errors);
358	        requireText("telephone", ownerFieldsDto.getTelephone(), errors);
359	        if (!errors.isEmpty()) {
360	            throw new RequiredFieldsMissingException(errors);
361	        }
362	    }
363	
364	    private static void requireText(String field, String value, List<String> errors) {
365	        if (value == null || value.isBlank()) {
366	            errors.add(field);
367	        }
368	    }
