370	    /**
371	     * Region -> inclusive 4-digit postcode range {@code {low, high}} used to validate a supplied
372	     * postcode against the owner's city. A region absent from this table (i.e. a city whose region
373	     * is {@code 'UNKNOWN'}) imposes no range, so any 4-digit postcode is accepted there.
374	     */
375	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
376	        "NSW", new int[] {2000, 2099},
377	        "VIC", new int[] {3000, 3099},
378	        "QLD", new int[] {4000, 4099});
379	
380	    /**
381	     * Validates the submitted {@code postcode} only when present. The field is optional, so a
382	     * {@code null} value is accepted. When present it has already been constrained to four digits
383	     * by Bean Validation; here it is additionally checked against the owner's city: for a city
384	     * whose region is known (see {@link org.springframework.samples.petclinic.mapper.LocalityLookup}),
385	     * the postcode must fall within that region's inclusive range
386	     * ({@link #REGION_POSTCODE_RANGE}); a city with no known region accepts any 4-digit value.
387	     *
388	     * @param ownerFieldsDto the submitted owner fields (city already validated as present)
389	     * @throws InvalidPostcodeException with a 400 status if the postcode is out of range for the
390	     *                                  city's region
391	     */
392	    private static void validatePostcode(OwnerFieldsDto ownerFieldsDto) {
393	        String postcode = ownerFieldsDto.getPostcode();
394	        if (postcode == null) {
395	            return;
396	        }
397	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
398	            .regionFor(ownerFieldsDto.getCity());
399	        int[] range = REGION_POSTCODE_RANGE.get(region);
400	        if (range == null) {
401	            return;
402	        }
403	        int value = Integer.parseInt(postcode);
404	        if (value < range[0] || value > range[1]) {
405	            throw new InvalidPostcodeException(postcode);
406	        }
407	    }
408	
409	    /**
410	     * Normalizes the submitted telephone on create to E.164 form (see {@link #toE164}) and
411	     * writes the canonical {@code '+'}-prefixed value back onto the request so it is persisted
412	     * and echoed back in that form.
413	     *
414	     * @param ownerFieldsDto the submitted owner fields
415	     * @throws RequiredFieldsMissingException with a 400 status if the telephone cannot form a
416	     *                                        valid E.164 number
417	     */
418	    private static void normalizeTelephone(OwnerFieldsDto ownerFieldsDto) {
419	        String e164 = toE164(ownerFieldsDto.getTelephone());
420	        if (e164 == null) {
421	            throw new RequiredFieldsMissingException(List.of("telephone"));
422	        }
423	        ownerFieldsDto.setTelephone(e164);
424	    }
425	
426	    /**
427	     * Converts a raw telephone to E.164 form, or returns {@code null} when it cannot form a
428	     * valid E.164 number. Spaces, dashes and brackets are stripped. When a leading {@code '+'}
429	     * and country code are present they are kept; otherwise country code {@code '+61'} is
430	     * assumed and a single leading {@code '0'} is dropped from the national digits. The result
431	     * must contain 8 to 15 digits after the {@code '+'}, and for the recognised country codes
432	     * the national-number length must match the country: {@code '+61'} (Australia) requires
433	     * exactly 9 national digits and {@code '+1'} (NANP) requires exactly 10.
434	     *
435	     * @param raw the submitted telephone, possibly {@code null}
436	     * @return the canonical E.164 string, or {@code null} if it is not a valid E.164 number
437	     */
438	    private static String toE164(String raw) {
439	        if (raw == null) {
440	            return null;
441	        }
442	        String cleaned = raw.replaceAll("[\\s\\-()]", "");
443	        String digits;
444	        if (cleaned.startsWith("+")) {
445	            digits = cleaned.substring(1);
446	        } else {
447	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
448	            digits = "61" + national;
449	        }
450	        if (!digits.matches("[0-9]{8,15}")) {
451	            return null;
452	        }
453	        if (digits.startsWith("61")) {
454	            // Australia: exactly 9 national digits after the '+61' country code.
455	            if (digits.length() - 2 != 9) {
456	                return null;
457	            }
458	        } else if (digits.startsWith("1")) {
459	            // NANP: exactly 10 national digits after the '+1' country code.
460	            if (digits.length() - 1 != 10) {
461	                return null;
462	            }
463	        }
464	        return "+" + digits;
465	    }
466	
467	    /**
468	     * Rejects a create whose E.164 telephone is already used by any existing owner. The
469	     * submitted telephone has already been normalized to E.164 by {@link #normalizeTelephone};
470	     * each stored owner's telephone is normalized the same way before comparison so differing
471	     * input formats collapse to the same value.
472	     *
473	     * @param normalizedTelephone the submitted, already-normalized E.164 telephone
474	     * @throws DuplicateTelephoneException with a 409 status if another owner already uses the
475	     *                                     same E.164 telephone
476	     */
477	    /**
478	     * Matches a syntactically valid email address: a non-empty local part, an {@code @},
479	     * and a domain of at least two dot-separated labels ending in an alphabetic TLD. None of
480	     * the parts may contain whitespace or a second {@code @}.
481	     */
482	    private static final Pattern EMAIL_PATTERN =
483	        Pattern.compile("^[^@\\s]+@[^@\\s]+\\.[A-Za-z]{2,}$");
484	
485	    /**
486	     * Disposable email domains that are not accepted for an owner's email. A create whose email
487	     * domain (the part after the {@code '@'}, compared case-insensitively) is on this blocklist is
488	     * rejected. Kept lower-cased to match the normalized email.
489	     */
490	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
491	        "mailinator.com",
492	        "tempmail.com",
493	        "guerrillamail.com");
494	
495	    /**
496	     * Normalizes the submitted email when present: the value is trimmed, required to be a
497	     * syntactically valid address, required not to use a disposable-email domain, and written back
498	     * lower-cased so it is persisted and echoed back in canonical form. A {@code null} email is
499	     * left untouched — the field is optional.
500	     *
501	     * @param ownerFieldsDto the submitted owner fields
502	     * @throws InvalidEmailException with a 400 status if the email is present but not syntactically
503	     *                               valid, or its domain is on the disposable-domain blocklist
504	     */
505	    private static void normalizeEmail(OwnerFieldsDto ownerFieldsDto) {
506	        String email = ownerFieldsDto.getEmail();
507	        if (email == null) {
508	            return;
509	        }
510	        String trimmed = email.strip();
511	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
512	            throw new InvalidEmailException(email);
513	        }
514	        String normalized = trimmed.toLowerCase(Locale.ROOT);
515	        String domain = normalized.substring(normalized.indexOf('@') + 1);
516	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
517	            throw new InvalidEmailException(email);
518	        }
519	        ownerFieldsDto.setEmail(normalized);
520	    }
521	
522	    /**
523	     * Rejects a create whose supplied {@code registrationDate} is later than the server's current
524	     * date. A registration may be back-dated but never post-dated. The check is made against the
525	     * value as supplied, before any defaulting or business-day roll (see
526	     * {@link #defaultRegistrationDate}); a {@code null} registration date is accepted (it defaults
527	     * to the server date).
528	     *
529	     * @param ownerFieldsDto the submitted owner fields
530	     * @throws FutureRegistrationDateException with a 400 status if the supplied registration date is
531	     *                                         after the server's current date
532	     */
533	    private static void rejectFutureRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
534	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
535	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
536	            throw new FutureRegistrationDateException(supplied);
537	        }
538	    }
