587	    /**
588	     * Assigns the owner's {@code customerCode} on create, formatted
589	     * {@code '<REGION>-<HASH8>'} where REGION is the region derived from the owner's postcode
590	     * (preferring the postcode range, falling back to the city — the same derivation that yields
591	     * the owner's {@code locality}, see
592	     * {@link org.springframework.samples.petclinic.mapper.LocalityLookup#regionFor(String, String)}),
593	     * and HASH8 is the first 8 upper-cased hex characters of the SHA-256 digest of the owner's
594	     * already-normalized (E.164) {@code telephone} concatenated with its {@code lastName} — e.g.
595	     * {@code 'NSW-A1B2C3D4'}. There is no per-city sequence: two owners in the same region share a
596	     * customer code only when their normalized telephone and last name both match.
597	     *
598	     * <p>When the computed customer code collides with an existing owner's {@code customerCode},
599	     * it is de-duplicated by appending {@code '-<n>'} with the smallest {@code n} of 2 or more that
600	     * makes it unique among the existing owners, so distinct owners always receive distinct codes.
601	     *
602	     * @param owner the owner being created (with its {@code postcode}, {@code city},
603	     *              {@code telephone} and {@code lastName} already set)
604	     */
605	    private void assignCustomerCode(Owner owner) {
606	        String region = org.springframework.samples.petclinic.mapper.LocalityLookup
607	            .regionFor(owner.getPostcode(), owner.getCity());
608	        String hash8 = sha256Hex(owner.getTelephone() + owner.getLastName())
609	            .substring(0, 8).toUpperCase(Locale.ROOT);
610	        String base = region + "-" + hash8;
611	        Set<String> existing = this.clinicService.findAllOwners().stream()
612	            .map(Owner::getCustomerCode)
613	            .filter(Objects::nonNull)
614	            .collect(Collectors.toSet());
615	        String customerCode = base;
616	        for (int n = 2; existing.contains(customerCode); n++) {
617	            customerCode = base + "-" + n;
618	        }
619	        owner.setCustomerCode(customerCode);
620	    }
