636	    /**
637	     * Derives the deterministic {@code householdId} for the given {@code lastName} and
638	     * {@code postcode}: the first 12 hex characters of the SHA-256 digest of the normalized
639	     * {@code lastName} (see {@link #collapse}) concatenated with a {@code '|'} and the
640	     * {@code postcode} (empty when absent). Because it is derived purely from those two fields,
641	     * every owner sharing a last name and postcode receives the same value, independent of create
642	     * order. Shared by {@link #assignHouseholdId} (which persists it), {@link #identityKeyFor}
643	     * (which folds it into the identity key for duplicate detection) and
644	     * {@link #rejectDuplicateHousehold} (which blocks a second owner in the same household).
645	     *
646	     * @param lastName the owner's last name
647	     * @param postcode the owner's postcode, possibly {@code null}
648	     * @return the derived household id
649	     */
650	    private static String householdIdFor(String lastName, String postcode) {
651	        String key = collapse(lastName) + "|" + (postcode == null ? "" : postcode);
652	        return sha256Hex(key).substring(0, 12);
653	    }
