655	    /**
656	     * Rejects a create whose computed {@code householdId} (derived from {@code lastName} and
657	     * {@code postcode}, see {@link #householdIdFor}) already belongs to an existing owner, unless
658	     * the request opts in via {@code sharesHousehold}. Because the household is keyed on
659	     * {@code (lastName, postcode)}, a second owner sharing both is the same household: it is
660	     * rejected with a 409 as a household duplicate unless it declares {@code sharesHousehold}, in
661	     * which case it is created as a declared household member. The scan is taken over the existing
662	     * owners before this one is persisted.
663	     *
664	     * @param ownerFieldsDto the submitted owner fields ({@code lastName} and {@code postcode} set)
665	     * @throws DuplicateHouseholdException with a 409 status if the household already exists and the
666	     *                                     request did not opt in via {@code sharesHousehold}
667	     */
668	    private void rejectDuplicateHousehold(OwnerFieldsDto ownerFieldsDto) {
669	        if (Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
670	            return;
671	        }
672	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
673	        boolean duplicate = this.clinicService.findAllOwners().stream()
674	            .filter(existing -> !existing.isDeleted())
675	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
676	        if (duplicate) {
677	            throw new DuplicateHouseholdException(ownerFieldsDto.getLastName(), ownerFieldsDto.getAddress());
678	        }
679	    }
