776	        if (declaredHouseholdMember) {
777	            owner.setPossibleDuplicate(false);
778	            owner.setPossibleDuplicateOf(null);
779	            return;
780	        }
781	        String lastName = owner.getLastName();
782	        String postcode = owner.getPostcode();
783	        String telephone = owner.getTelephone();
784	        Integer matchId = null;
785	        if (lastName != null && postcode != null && telephone != null) {
786	            matchId = this.clinicService.findAllOwners().stream()
787	                .filter(existing -> lastName.equalsIgnoreCase(existing.getLastName()))
788	                .filter(existing -> postcode.equals(existing.getPostcode()))
789	                .filter(existing -> !telephone.equals(existing.getTelephone()))
790	                .map(Owner::getId)
791	                .filter(id -> id != null)
792	                .min(Integer::compareTo)
793	                .orElse(null);
794	        }
795	        owner.setPossibleDuplicate(matchId != null);
796	        owner.setPossibleDuplicateOf(matchId);
