799	    /**
800	     * Returns the lower-case hex SHA-256 digest of the UTF-8 bytes of {@code value}.
801	     *
802	     * @param value the string to hash
803	     * @return the 64-character lower-case hex digest
804	     */
805	    private static String sha256Hex(String value) {
806	        try {
807	            byte[] digest = MessageDigest.getInstance("SHA-256")
808	                .digest(value.getBytes(StandardCharsets.UTF_8));
809	            StringBuilder sb = new StringBuilder(digest.length * 2);
810	            for (byte b : digest) {
811	                sb.append(String.format("%02x", b));
812	            }
813	            return sb.toString();
814	        }
815	        catch (NoSuchAlgorithmException e) {
816	            throw new IllegalStateException("SHA-256 not available", e);
817	        }
818	    }
