908	     * @param businessDay the effective, business-day-adjusted registration date of this create
909	     * @throws DailyOwnerLimitExceededException with a 429 status if the day is already at the limit
910	     */
911	    private void rejectDailyLimit(LocalDate businessDay) {
912	        long count = this.clinicService.findAllOwners().stream()
913	            .filter(existing -> businessDay.equals(existing.getRegistrationDate()))
914	            .count();
915	        if (count >= DAILY_LIMIT) {
916	            throw new DailyOwnerLimitExceededException(businessDay);
917	        }
918	    }
