312	        int points = 0;
313	        if (this.email != null && !this.email.isBlank()) {
314	            points += 2;
315	        }
316	        if (this.namesakeCount != null && this.namesakeCount == 0) {
317	            points += 1;
318	        }
319	        if (this.householdMemberCount != null && this.householdMemberCount >= 3) {
320	            points += 2;
321	        }
322	        if (this.registrationDate != null
323	                && fiscalYearOf(LocalDate.now()) - fiscalYearOf(this.registrationDate) >= 1) {
