388	    /**
389	     * The owner's check digit, derived on read: a single Luhn check digit computed over the
390	     * digits contained in the owner's {@code customerCode}.
391	     *
392	     * @return the Luhn check digit (0-9), or {@code null} when no customer code is assigned
393	     */
394	    @Transient
395	    public Integer getCheckDigit() {
396	        if (this.customerCode == null) {
397	            return null;
398	        }
399	        int sum = 0;
400	        boolean dbl = true;
401	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
402	            char c = this.customerCode.charAt(i);
403	            if (c < '0' || c > '9') {
404	                continue;
405	            }
406	            int d = c - '0';
407	            if (dbl) {
408	                d *= 2;
409	                if (d > 9) {
410	                    d -= 9;
411	                }
412	            }
413	            sum += d;
414	            dbl = !dbl;
415	        }
416	        return (10 - (sum % 10)) % 10;
417	    }
