419	    /**
420	     * The owner's stored E.164 {@code telephone} formatted for humans, derived on read: the
421	     * leading {@code '+'} and country code, a space, then the national digits grouped in threes
422	     * (e.g. {@code '+61 412 345 678'} for a stored {@code '+61412345678'}). The recognised
423	     * country codes are {@code '+61'} (Australia) and {@code '+1'} (NANP); any other prefix falls
424	     * back to a two-digit country code. The raw {@code telephone} is left in E.164 form.
425	     *
426	     * @return the human-formatted telephone, or the raw value when it is not in E.164 form
427	     */
428	    @Transient
429	    public String getTelephoneDisplay() {
430	        if (this.telephone == null || !this.telephone.startsWith("+")
431	                || !this.telephone.substring(1).matches("[0-9]+")) {
432	            return this.telephone;
433	        }
434	        String digits = this.telephone.substring(1);
435	        String countryCode;
436	        if (digits.startsWith("61")) {
437	            countryCode = "61";
438	        } else if (digits.startsWith("1")) {
439	            countryCode = "1";
440	        } else {
441	            countryCode = digits.length() > 2 ? digits.substring(0, 2) : digits;
442	        }
443	        String national = digits.substring(countryCode.length());
444	        StringBuilder display = new StringBuilder("+").append(countryCode);
445	        for (int i = 0; i < national.length(); i += 3) {
446	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
447	        }
448	        return display.toString();
449	    }
