3	import java.util.Map;
4	
5	/**
6	 * Derives an owner's {@code locality} from its postcode and city. The postcode
7	 * range is preferred: it is looked up against the fixed region ranges first, and
8	 * only when the postcode is absent or falls in no known range does the derivation
9	 * fall back to the fixed city-to-region table. Kept out of the mapper interface
10	 * deliberately: MapStruct treats any single-argument method on a {@code @Mapper}
11	 * interface as a candidate mapping method, so a {@code String -> String} helper
12	 * there would be applied to every String property. This static lookup is
13	 * referenced only from an explicit mapping expression instead.
14	 */
15	public final class LocalityLookup {
16	
17	    /** City -> canonical region; an exact, case-sensitive mapping. */
18	    private static final Map<String, String> CITY_REGION = Map.of(
19	        "Sydney", "NSW",
20	        "Melbourne", "VIC",
21	        "Brisbane", "QLD");
22	
23	    /** Region -> inclusive 4-digit postcode range {low, high}. */
24	    private static final Map<String, int[]> REGION_POSTCODES = Map.of(
25	        "NSW", new int[] {2000, 2099},
26	        "VIC", new int[] {3000, 3099},
27	        "QLD", new int[] {4000, 4099});
28	
29	    /** Region -> IANA timezone name; a fixed, exact mapping. */
30	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
31	        "NSW", "Australia/Sydney",
32	        "VIC", "Australia/Melbourne",
33	        "QLD", "Australia/Brisbane");
34	
35	    private LocalityLookup() {
36	    }
37	
38	    /**
39	     * Returns the canonical region for {@code city} from the fixed table, or
40	     * {@code 'UNKNOWN'} when the city is not in the table.
41	     *
42	     * @param city the owner's city, possibly {@code null}
43	     * @return the canonical region, or {@code 'UNKNOWN'} if the city is unknown
44	     */
45	    public static String regionFor(String city) {
46	        return CITY_REGION.getOrDefault(city, "UNKNOWN");
47	    }
48	
49	    /**
50	     * Returns the canonical region, preferring the postcode over the city. The
51	     * postcode is matched against the fixed region ranges first; only when it is
52	     * absent or in no known range does the lookup fall back to the city table.
53	     * This yields the same region for known cities but disambiguates cities that
54	     * share a name.
55	     *
56	     * @param postcode the owner's postcode, possibly {@code null}
57	     * @param city the owner's city, possibly {@code null}
58	     * @return the canonical region, or {@code 'UNKNOWN'} if neither resolves
59	     */
60	    public static String regionFor(String postcode, String city) {
61	        String fromPostcode = regionForPostcode(postcode);
62	        return fromPostcode != null ? fromPostcode : regionFor(city);
63	    }
64	
65	    /**
66	     * Returns the IANA timezone name for the region derived from {@code postcode}
67	     * and {@code city}, from the fixed region-to-timezone table, or {@code null}
68	     * when the region is not in the table.
69	     *
70	     * @param postcode the owner's postcode, possibly {@code null}
71	     * @param city the owner's city, possibly {@code null}
72	     * @return the IANA timezone name, or {@code null} if the region is unknown
73	     */
74	    public static String timezoneFor(String postcode, String city) {
75	        return REGION_TIMEZONE.get(regionFor(postcode, city));
76	    }
77	
78	    /**
79	     * Returns the canonical region whose postcode range contains {@code postcode},
80	     * or {@code null} when the postcode is absent, non-numeric, or in no known range.
81	     */
82	    private static String regionForPostcode(String postcode) {
83	        if (postcode == null) {
84	            return null;
85	        }
86	        int value;
87	        try {
88	            value = Integer.parseInt(postcode.trim());
89	        }
90	        catch (NumberFormatException ex) {
91	            return null;
92	        }
93	        for (Map.Entry<String, int[]> entry : REGION_POSTCODES.entrySet()) {
94	            int[] range = entry.getValue();
95	            if (value >= range[0] && value <= range[1]) {
96	                return entry.getKey();
97	            }
98	        }
99	        return null;
100	    }
101	}
